/**
 * Terminal session manager (spec §6.1, §17).
 *
 * Owns every pseudo-terminal of the application. The renderer never receives
 * a process handle, a command string or a Node.js API — it can only create a
 * session, write to it, resize it and kill it (spec §17).
 *
 * Security rules enforced here:
 *  - A session always starts inside the active workspace; the renderer may
 *    only narrow that to a sub-directory of the workspace (resolved through
 *    `resolveInWorkspace`, never trusted as given).
 *  - Session ids are generated by the main process and are unguessable.
 *  - Every session is killed when the workspace closes or the app quits, so
 *    no child process is orphaned.
 */
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import type {
  FsResult,
  TerminalExit,
  TerminalSession,
} from '../../shared/ipc-types';
import { resolveInWorkspace } from './pathSecurity';
import { fsFail, fsOk } from './results';
import {
  killProcessTree,
  loadPty,
  ptyUnavailable,
  type PtyProcess,
} from './processTree';

/** Maximum number of concurrent terminal sessions. */
const MAX_SESSIONS = 8;
/** Smallest accepted terminal size. */
const MIN_COLS = 1;
const MIN_ROWS = 1;
/** Largest accepted terminal size (guards against absurd allocations). */
const MAX_COLS = 1000;
const MAX_ROWS = 1000;
/**
 * Exit code reported for a session that was killed by the application.
 *
 * It follows the shell convention for "terminated by a signal"
 * (128 + SIGKILL) so the renderer can tell a kill from a failure.
 */
export const TERMINAL_KILLED_EXIT_CODE = 137;

/** A live session together with its bookkeeping. */
interface Session {
  id: string;
  process: PtyProcess;
  cwd: string;
  shell: string;
  cols: number;
  rows: number;
  /** Disposables for the node-pty event listeners. */
  subscriptions: { dispose(): void }[];
}

/** Default shell per platform (spec §17). */
export interface ShellSpec {
  /** Executable to start. */
  file: string;
  /** Arguments passed to the executable. */
  args: string[];
  /** Display name. */
  name: string;
}

/**
 * Resolves the shell to start.
 *
 * Windows uses PowerShell (the platform default), macOS/Linux use the
 * user's login shell (`$SHELL`), falling back to `/bin/bash`.
 */
export function resolveDefaultShell(
  platform: NodeJS.Platform = process.platform,
  env: NodeJS.ProcessEnv = process.env,
): ShellSpec {
  if (platform === 'win32') {
    return { file: 'powershell.exe', args: ['-NoLogo'], name: 'PowerShell' };
  }
  const shell = env.SHELL;
  if (typeof shell === 'string' && shell.length > 0) {
    return { file: shell, args: ['-l'], name: path.basename(shell) };
  }
  return { file: '/bin/bash', args: ['-l'], name: 'bash' };
}

export interface TerminalServiceOptions {
  /** Returns the canonical root of the active workspace, or null. */
  getRoot: () => string | null;
  /** Called for every output chunk of every session. */
  onData: (sessionId: string, data: string) => void;
  /** Called when a session ends. */
  onExit: (exit: TerminalExit) => void;
  /**
   * Called when a shell process starts, so it can be terminated if the
   * application dies unexpectedly.
   */
  onProcessStart?: (pid: number) => void;
  /** Called when a shell process is gone. */
  onProcessEnd?: (pid: number) => void;
}

export class TerminalService {
  private readonly sessions = new Map<string, Session>();
  private readonly getRoot: () => string | null;
  private readonly onData: (sessionId: string, data: string) => void;
  private readonly onExit: (exit: TerminalExit) => void;
  private readonly onProcessStart: ((pid: number) => void) | undefined;
  private readonly onProcessEnd: ((pid: number) => void) | undefined;

  constructor(options: TerminalServiceOptions) {
    this.getRoot = options.getRoot;
    this.onData = options.onData;
    this.onExit = options.onExit;
    this.onProcessStart = options.onProcessStart;
    this.onProcessEnd = options.onProcessEnd;
  }

  /** Number of live sessions (used by tests and diagnostics). */
  get sessionCount(): number {
    return this.sessions.size;
  }

  /**
   * Creates a session.
   *
   * `requestedCwd` is optional and always treated as untrusted: it is
   * resolved through `resolveInWorkspace`, so traversal, symlink and
   * junction escapes are rejected. The default is the workspace root.
   */
  async create(requestedCwd?: string): Promise<FsResult<TerminalSession>> {
    const root = this.getRoot();
    if (root === null) {
      return fsFail('NO_WORKSPACE', 'Open a folder before starting a terminal');
    }
    if (this.sessions.size >= MAX_SESSIONS) {
      return fsFail(
        'UNKNOWN',
        `Too many terminal sessions (limit ${MAX_SESSIONS})`,
      );
    }

    const pty = loadPty();
    if (pty === null) {
      return fsFail(
        'UNKNOWN',
        `The terminal backend is unavailable: ${ptyUnavailable()}`,
      );
    }

    // Resolve the working directory inside the workspace (async, because
    // canonicalisation touches the filesystem).
    const resolved = await this.resolveCwd(root, requestedCwd);
    if (!resolved.ok) {
      return resolved;
    }
    const shell = resolveDefaultShell();
    const cols = 80;
    const rows = 24;
    const id = randomUUID();

    let child: PtyProcess;
    try {
      child = pty.spawn(shell.file, shell.args, {
        name: 'xterm-256color',
        cols,
        rows,
        cwd: resolved.value,
        env: {
          ...process.env,
          TERM: 'xterm-256color',
          COLORTERM: 'truecolor',
        },
        encoding: 'utf8',
      });
    } catch (error) {
      console.error('[terminal] could not start the shell:', error);
      return fsFail('UNKNOWN', 'Could not start the terminal shell');
    }

    const subscriptions: { dispose(): void }[] = [];
    const session: Session = {
      id,
      process: child,
      cwd: resolved.value,
      shell: shell.name,
      cols,
      rows,
      subscriptions,
    };
    this.sessions.set(id, session);

    subscriptions.push(
      child.onData((data) => {
        this.onData(id, data);
      }),
    );
    this.onProcessStart?.(child.pid);
    subscriptions.push(
      child.onExit((event) => {
        // The session may already have been disposed by an explicit kill;
        // in that case the exit was reported there.
        if (!this.sessions.has(id)) {
          return;
        }
        this.disposeSession(id);
        this.onExit({ sessionId: id, exitCode: event.exitCode });
      }),
    );

    return fsOk<TerminalSession>({
      id,
      shell: shell.name,
      cwd: resolved.value,
      cols,
      rows,
    });
  }

  /** Writes user input to a session. */
  write(sessionId: string, data: string): FsResult<void> {
    const session = this.sessions.get(sessionId);
    if (session === undefined) {
      return fsFail('NOT_FOUND', 'The terminal session no longer exists');
    }
    try {
      session.process.write(data);
    } catch (error) {
      console.error('[terminal] write failed:', error);
      return fsFail('UNKNOWN', 'Could not write to the terminal');
    }
    return fsOk<void>(undefined);
  }

  /** Resizes a session's pseudo-terminal. */
  resize(sessionId: string, cols: number, rows: number): FsResult<void> {
    const session = this.sessions.get(sessionId);
    if (session === undefined) {
      return fsFail('NOT_FOUND', 'The terminal session no longer exists');
    }
    if (
      !Number.isInteger(cols) ||
      !Number.isInteger(rows) ||
      cols < MIN_COLS ||
      rows < MIN_ROWS ||
      cols > MAX_COLS ||
      rows > MAX_ROWS
    ) {
      return fsFail('INVALID_PATH', 'Invalid terminal size');
    }
    try {
      session.process.resize(cols, rows);
      session.cols = cols;
      session.rows = rows;
    } catch (error) {
      console.error('[terminal] resize failed:', error);
      return fsFail('UNKNOWN', 'Could not resize the terminal');
    }
    return fsOk<void>(undefined);
  }

  /** Kills a session and its process tree. */
  kill(sessionId: string): FsResult<void> {
    if (!this.sessions.has(sessionId)) {
      return fsFail('NOT_FOUND', 'The terminal session no longer exists');
    }
    // The exit is reported explicitly: a killed shell does not always
    // deliver an exit event of its own.
    this.disposeSession(sessionId);
    this.onExit({ sessionId, exitCode: TERMINAL_KILLED_EXIT_CODE });
    return fsOk<void>(undefined);
  }

  /**
   * Kills every session (workspace closed, app quitting).
   *
   * The promise resolves when the process trees are really gone, so the
   * application can wait for it before it quits.
   *
   * Safe to call more than once.
   */
  async killAll(): Promise<void> {
    const pending: Promise<void>[] = [];
    for (const id of [...this.sessions.keys()]) {
      pending.push(this.disposeSession(id));
      this.onExit({ sessionId: id, exitCode: TERMINAL_KILLED_EXIT_CODE });
    }
    await Promise.all(pending);
  }

  /**
   * Removes a session and terminates its process tree.
   *
   * The exit is reported by the caller: an explicit kill reports the exit
   * itself (the shell may not report one when it is terminated), while a
   * session that ends on its own reports the exit code of the shell.
   */
  private async disposeSession(sessionId: string): Promise<void> {
    const session = this.sessions.get(sessionId);
    if (session === undefined) {
      return;
    }
    this.sessions.delete(sessionId);
    for (const subscription of session.subscriptions) {
      try {
        subscription.dispose();
      } catch {
        // A disposed listener must never break the teardown.
      }
    }
    session.subscriptions.length = 0;
    this.onProcessEnd?.(session.process.pid);
    // The process tree is terminated BEFORE the shell itself: on Windows
    // `taskkill /T` resolves the descendants through their parent, so
    // killing the shell first would detach the children.
    await killProcessTree(session.process.pid);
    try {
      session.process.kill();
    } catch (error) {
      // The tree is already gone (or node-pty could not enumerate the
      // console processes because its helper is not available in the
      // hardened build) — the shell is terminated either way.
      console.warn('[terminal] the shell was already terminated:', error);
    }
  }
  /** Resolves the requested working directory inside the workspace. */
  private async resolveCwd(
    root: string,
    requestedCwd: string | undefined,
  ): Promise<FsResult<string>> {
    if (requestedCwd === undefined || requestedCwd === '') {
      return fsOk(root);
    }
    const resolved = await resolveInWorkspace(root, requestedCwd, {
      allowRoot: true,
      mustExist: true,
    });
    if (!resolved.ok) {
      return fsFail(resolved.code, 'The terminal folder is outside the workspace');
    }
    return fsOk(resolved.value);
  }
}

